#!/usr/bin/env python3
"""Pictures for vocabulary items: hand-drawn SVG files, plus pictures generated by Cloudflare Workers AI.

Hand-drawn: apps/miniapp/public/img/<lang>/<id>.svg, committed as they are. They always win over generated pictures
and are never deleted here.
Generated: scripts/images/*.yaml — item id → what to draw (one English sentence), or `~` for "no generated picture"
(function words, abstract words: a vague picture is worse than none). The style is added here, the same for all.
Files go to apps/miniapp/public/img/<lang>/<id>.webp; only pictures whose prompt, style or model changed are drawn
again; pictures of removed prompts are deleted.
Both kinds are listed in apps/miniapp/public/img/manifest.json: {id: "<lang>/<file>?v=<hash>"}.

Generating needs CLOUDFLARE_API_TOKEN (Workers AI permission) in the environment or in apps/worker/.dev.vars;
the account id comes from CLOUDFLARE_ACCOUNT_ID or apps/worker/wrangler.toml. Python packages: pyyaml (+ requests, pillow).

Usage:
  python3 scripts/images.py [--dry-run] [--limit N] [--redo ID ...]
  python3 scripts/images.py --local       # no generation: only refresh the manifest from the files on disk
  python3 scripts/images.py --sheet       # .cache/images-<lang>.html: every picture with its word, to check by eye
  python3 scripts/images.py --self-test   # checks the pure logic, no network needed
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import html
import io
import json
import os
import re
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PROMPTS = ROOT / "scripts/images"
OUT = ROOT / "apps/miniapp/public/img"
MANIFEST = OUT / "manifest.json"

MODEL = "@cf/black-forest-labs/flux-1-schnell"
STEPS = 4
# The model cannot spell: any writing in a picture comes out as nonsense, so ask for none.
STYLE = "Flat vector illustration, simple clean shapes, soft warm colors, plain light background, centered, no text, no letters, no numbers."
SIZE = 384  # px, square; about 15–25 KB as WebP
QUALITY = 80
ID = re.compile(r"^(lt|es|fr)-(w|p)-\d{4}$")


def lang_of(item_id: str) -> str:
    return item_id[:2]


def file_name(item_id: str, ext: str = "webp") -> str:
    return f"{lang_of(item_id)}/{item_id}.{ext}"


def entry(item_id: str, ext: str, version: str) -> str:
    """Manifest value: the file inside /img plus a version, so that a changed picture is not served from the cache."""
    return f"{file_name(item_id, ext)}?v={version}"


def full_prompt(scene: str) -> str:
    return f"{scene.strip().rstrip('.')}. {STYLE}"


def prompt_hash(scene: str) -> str:
    """Changes when anything that affects the picture changes."""
    return hashlib.sha256(f"{MODEL}|{STEPS}|{SIZE}|{full_prompt(scene)}".encode()).hexdigest()[:10]


def plan(prompts: dict, manifest: dict, drawn: dict, redo: set[str] = frozenset()) -> tuple[dict, list[tuple[str, str]], list[str]]:
    """Returns (wanted generated entries, jobs [(id, scene)] to draw, relative files to delete).

    `drawn` is {id: manifest entry} of the hand-drawn files: those items are not generated.
    """
    wanted = {i: entry(i, "webp", prompt_hash(scene)) for i, scene in prompts.items() if scene and i not in drawn}
    jobs = [(i, prompts[i]) for i, e in wanted.items() if manifest.get(i) != e or i in redo]
    stale = [file_name(i) for i, e in manifest.items() if ".webp?" in e and i not in wanted]
    return wanted, jobs, stale


def load_prompts() -> dict:
    import yaml

    prompts: dict = {}
    for path in sorted(PROMPTS.glob("*.yaml")):
        for item_id, scene in (yaml.safe_load(path.read_text(encoding="utf-8")) or {}).items():
            if not ID.match(str(item_id)):
                raise SystemExit(f"✗ {path.name}: '{item_id}' is not an item id")
            if item_id in prompts:
                raise SystemExit(f"✗ {path.name}: {item_id} is listed twice")
            if scene is not None and not (isinstance(scene, str) and scene.strip()):
                raise SystemExit(f"✗ {path.name}: {item_id} needs a sentence or ~")
            prompts[item_id] = scene
    return prompts


def load_drawn() -> dict:
    """Hand-drawn SVG files on disk: {id: manifest entry}."""
    drawn: dict = {}
    for path in sorted(OUT.glob("*/*.svg")):
        if not ID.match(path.stem) or path.parent.name != lang_of(path.stem):
            raise SystemExit(f"✗ {path.relative_to(ROOT)}: the file name must be an item id inside its language folder")
        drawn[path.stem] = entry(path.stem, "svg", hashlib.sha256(path.read_bytes()).hexdigest()[:10])
    return drawn


def load_items() -> dict:
    """Vocabulary and phrasebook items by id (for checking ids and for the contact sheet)."""
    import yaml

    items: dict = {}
    for path in sorted(ROOT.glob("content/*/vocab/*.yaml")) + sorted(ROOT.glob("content/*/phrasebook/*.yaml")):
        for item in yaml.safe_load(path.read_text(encoding="utf-8")) or []:
            items[item["id"]] = item
    return items


def credentials() -> tuple[str, str]:
    token = os.environ.get("CLOUDFLARE_API_TOKEN", "")
    account = os.environ.get("CLOUDFLARE_ACCOUNT_ID", "")
    dev_vars = ROOT / "apps/worker/.dev.vars"
    if not token and dev_vars.exists():
        m = re.search(r"^CLOUDFLARE_API_TOKEN=(\S+)", dev_vars.read_text(encoding="utf-8"), re.M)
        token = m.group(1) if m else ""
    if not account:
        m = re.search(r'^account_id\s*=\s*"([0-9a-f]+)"', (ROOT / "apps/worker/wrangler.toml").read_text(encoding="utf-8"), re.M)
        account = m.group(1) if m else ""
    if not token or not account:
        raise SystemExit("✗ set CLOUDFLARE_API_TOKEN (Workers AI permission) in the environment or in apps/worker/.dev.vars")
    return token, account


class DailyLimit(Exception):
    pass


def draw(scene: str, token: str, account: str) -> bytes:
    """One picture as WebP bytes."""
    import requests
    from PIL import Image

    url = f"https://api.cloudflare.com/client/v4/accounts/{account}/ai/run/{MODEL}"
    r = requests.post(url, headers={"Authorization": f"Bearer {token}"}, json={"prompt": full_prompt(scene), "steps": STEPS}, timeout=120)
    if r.status_code == 429:
        raise DailyLimit(r.text[:200])
    if r.status_code in (401, 403):
        raise SystemExit(f"✗ Cloudflare refused the token ({r.status_code}): {r.text[:200]}")
    r.raise_for_status()
    image = Image.open(io.BytesIO(base64.b64decode(r.json()["result"]["image"]))).convert("RGB")
    image = image.resize((SIZE, SIZE), Image.LANCZOS)
    out = io.BytesIO()
    image.save(out, "WEBP", quality=QUALITY, method=6)
    return out.getvalue()


def write_manifest(manifest: dict) -> None:
    tmp = MANIFEST.with_suffix(".tmp")
    tmp.write_text(json.dumps({i: manifest[i] for i in sorted(manifest)}, separators=(",", ":")) + "\n", encoding="utf-8")
    tmp.replace(MANIFEST)


def generate(jobs: list[tuple[str, str]], manifest: dict, wanted: dict) -> int:
    token, account = credentials()
    failed = 0
    for n, (item_id, scene) in enumerate(jobs, 1):
        path = OUT / file_name(item_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        for attempt in range(3):
            try:
                path.write_bytes(draw(scene, token, account))
                manifest[item_id] = wanted[item_id]
                write_manifest(manifest)  # keep progress if interrupted
                break
            except DailyLimit as e:
                print(f"… the free allowance for today is used up after {n - 1} picture(s); run again tomorrow ({e})")
                return failed
            except Exception as e:  # network hiccups: retry a couple of times
                if attempt == 2:
                    failed += 1
                    print(f"✗ {item_id}: {e}", file=sys.stderr)
                else:
                    time.sleep(2 * (attempt + 1))
        if n % 10 == 0:
            print(f"  … {n}/{len(jobs)}", flush=True)
    return failed


def sheets(prompts: dict, manifest: dict, items: dict) -> None:
    """One HTML page per language with every picture next to its word, meaning and prompt."""
    cache = ROOT / ".cache"
    cache.mkdir(exist_ok=True)
    for lang in sorted({lang_of(i) for i in manifest}):
        cells = []
        for item_id in sorted(i for i in manifest if lang_of(i) == lang):
            item = items.get(item_id, {})
            meaning = item.get("meaning", {})
            cells.append(
                f'<figure><img src="{(OUT / manifest[item_id].split("?")[0]).as_uri()}" loading="lazy"><figcaption><b>{html.escape(item.get("text", "?"))}</b> '
                f'<small>{item_id}</small><br>{html.escape(meaning.get("ru") or meaning.get("en") or "")}<br>'
                f'<small>{"hand-drawn" if ".svg?" in manifest[item_id] else html.escape(prompts.get(item_id) or "")}</small></figcaption></figure>'
            )
        page = (
            '<!doctype html><meta charset="utf-8"><title>Pictures: ' + lang + "</title><style>"
            "body{font:14px system-ui;margin:16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px}"
            "figure{margin:0}img{width:100%;border-radius:12px;background:#eee}small{color:#777}</style>" + "".join(cells)
        )
        path = cache / f"images-{lang}.html"
        path.write_text(page, encoding="utf-8")
        print(f"✓ {path.relative_to(ROOT)}: {len(cells)} pictures")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true", help="only show what would change")
    ap.add_argument("--limit", type=int, default=0, help="draw at most N pictures (for trying out)")
    ap.add_argument("--redo", nargs="*", default=[], metavar="ID", help="draw these again (a bad picture)")
    ap.add_argument("--local", action="store_true", help="generate nothing, only refresh the manifest from the files on disk")
    ap.add_argument("--sheet", action="store_true", help="write .cache/images-<lang>.html for checking by eye")
    ap.add_argument("--self-test", action="store_true")
    args = ap.parse_args()
    if args.self_test:
        return self_test()

    prompts = load_prompts()
    drawn = load_drawn()
    items = load_items()
    unknown = [i for i in [*prompts, *drawn] if i not in items]
    if unknown:
        print(f"✗ no such item: {', '.join(unknown[:10])}", file=sys.stderr)
        return 1
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8")) if MANIFEST.exists() else {}
    if args.sheet:
        sheets(prompts, manifest, items)
        return 0

    wanted, jobs, stale = plan(prompts, manifest, drawn, set(args.redo))
    if args.local:
        jobs = []
    elif args.limit:
        jobs = jobs[: args.limit]
    print(f"images: {len(drawn)} hand-drawn, {len(jobs)} to generate, {len(stale)} to delete, {len(wanted)} generated in total")
    if args.dry_run:
        for item_id, scene in jobs[:20]:
            print(f"  + {item_id} {items[item_id]['text']}: {scene}")
        for s in stale[:20]:
            print(f"  - {s}")
        return 0

    OUT.mkdir(parents=True, exist_ok=True)
    for rel in stale:
        (OUT / rel).unlink(missing_ok=True)
    # Keep only generated entries that are still wanted and unchanged; new ones are added back as they finish.
    manifest = {i: e for i, e in manifest.items() if wanted.get(i) == e} | drawn
    failed = generate(jobs, manifest, wanted) if jobs else 0
    write_manifest(manifest)

    files = [p for p in OUT.rglob("*") if p.suffix in (".webp", ".svg")]
    size = sum(p.stat().st_size for p in files)
    print(f"✓ {len(files)} files, {size / 1024 / 1024:.2f} MiB in {OUT.relative_to(ROOT)}")
    if failed:
        print(f"✗ {failed} picture(s) failed; run again to retry", file=sys.stderr)
        return 1
    return 0


def self_test() -> int:
    """Checks the incremental logic without network access."""
    prompts = {"es-w-0012": "A small house with a red roof", "es-w-0013": None, "lt-w-0001": "A clock"}
    wanted, jobs, stale = plan(prompts, {}, {})
    assert [j[0] for j in jobs] == ["es-w-0012", "lt-w-0001"], jobs
    assert stale == [] and "es-w-0013" not in wanted
    assert wanted["es-w-0012"].startswith("es/es-w-0012.webp?v=")

    # Nothing changed → nothing to do; --redo draws one again.
    assert plan(prompts, wanted, {})[1:] == ([], [])
    assert [j[0] for j in plan(prompts, wanted, {}, {"lt-w-0001"})[1]] == ["lt-w-0001"]

    # Changed prompt → draw again; prompt removed or set to ~ → the file is deleted.
    _, jobs3, stale3 = plan({"es-w-0012": "A big house", "lt-w-0001": None}, wanted, {})
    assert [j[0] for j in jobs3] == ["es-w-0012"] and stale3 == ["lt/lt-w-0001.webp"], (jobs3, stale3)

    # A hand-drawn file wins: nothing is generated for it, an old generated file goes, the SVG itself is never deleted.
    drawn = {"es-w-0012": entry("es-w-0012", "svg", "abc")}
    w4, jobs4, stale4 = plan(prompts, wanted, drawn)
    assert "es-w-0012" not in w4 and jobs4 == [] and stale4 == ["es/es-w-0012.webp"], (w4, jobs4, stale4)
    assert plan(prompts, wanted | drawn, drawn)[2] == []

    assert file_name("es-w-0012") == "es/es-w-0012.webp" and entry("es-w-0012", "svg", "abc") == "es/es-w-0012.svg?v=abc"
    assert full_prompt("A clock.").startswith("A clock. Flat") and prompt_hash("a") != prompt_hash("b")
    print("✓ images.py self-test")
    return 0


if __name__ == "__main__":
    os.chdir(ROOT)
    for stream in (sys.stdout, sys.stderr):  # Windows consoles default to cp1252, which cannot print ✓ / ✗
        stream.reconfigure(encoding="utf-8", errors="replace")
    sys.exit(main())
